def root_word_signature(value):
    # Complete parsed-JSON value and type equality, not rounded numbers or
    # numerical closeness. JSON distinguishes bool/int/float and negative zero.
    # The original Reader.safe_selected remains responsible for nonfinite
    # JSON scalar display; no IEEE NaN payload identity is claimed.
    return json.dumps(value,sort_keys=True,ensure_ascii=True,
                      separators=(",",":"),allow_nan=True)


def root_word_equal(left,right):
    """Exact selected JSON types/values; -0 stays distinct; NaN never shares."""
    if type(left) is not type(right):return False
    if isinstance(left,float):
        if math.isnan(left) or math.isnan(right):return False
        return left==right and (left!=0 or math.copysign(1,left)==math.copysign(1,right))
    if isinstance(left,dict):
        return left.keys()==right.keys() and all(root_word_equal(left[k],right[k]) for k in left)
    if isinstance(left,list):
        return len(left)==len(right) and all(root_word_equal(a,b) for a,b in zip(left,right))
    return left==right


def root_word_table(values):
